import{c as a,Q as i,j as t,m as o}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"When Summaries Distort Decisions: Information Fidelity in LLM-Compressed Financial Analysis","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.29251","title":"When Summaries Distort Decisions: Information Fidelity in LLM-Compressed Financial Analysis","archived_date":"2026-07-17T00:00:00.000Z","arxiv_id":2606.29251,"authors":["Hoyoung Lee","Suhwan Park","Seunghan Lee","Jun Seo","Jaehoon Lee","Sungdong Yoo","Minjae Kim","CheolWon Na","Zhangyang Wang","Zach Golkhou","Minkyu Kim","Sotirios Sabanis","Alejandro Lopez-Lira","Dhagash Mehta","Soonyoung Lee","Chanyeol Choi","Wonbin Ahn","Yongjae Lee"],"domains":["cs.AI","q-fin.CP"],"html":"https://arxiv.org/html/2606.29251v1","pdf_path":"pdfs/2606.29251.pdf","published_date":"2026-06-28T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-28-when-summaries-distort-decisions-information-fidelity-2606-29251.md","filePath":"research/papers/2026-06-28-when-summaries-distort-decisions-information-fidelity-2606-29251.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-06-28-when-summaries-distort-decisions-information-fidelity-2606-29251.md"};function s(n,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="when-summaries-distort-decisions-information-fidelity-in-llm-compressed-financial-analysis" tabindex="-1">When Summaries Distort Decisions: Information Fidelity in LLM-Compressed Financial Analysis <a class="header-anchor" href="#when-summaries-distort-decisions-information-fidelity-in-llm-compressed-financial-analysis" aria-label="Permalink to &quot;When Summaries Distort Decisions: Information Fidelity in LLM-Compressed Financial Analysis&quot;">​</a></h1><p><strong>Authors</strong>: Hoyoung Lee et al.（18 位作者） <strong>Published</strong>: June 28, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.29251" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.29251</a> · <a href="https://arxiv.org/html/2606.29251v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.29251 <strong>Categories</strong>: cs.AI, q-fin.CP <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.29251" target="_blank" rel="noreferrer">research/papers/pdfs/2606.29251.pdf</a></p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>（WebFetch 取得為摘述版，逐字全文未取得；以下為抓取內容）Financial decision-makers face challenges when LLMs compress source material — &quot;compression loses fidelity when it changes the decision induced by the source.&quot; The paper identifies two diagnostic patterns causing information loss: decontextualization (salient evidence retained but separated from the caveats and contextual qualifiers needed for correct interpretation) and model dependency (different compressors produce varying interpretations). It proposes Agentic Context Compression, which &quot;generates multiple candidate compressions and audits their disagreements against the original source.&quot;</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出「decision fidelity」視角：壓縮保真的判準不是表面事實正確，而是<strong>壓縮後是否改變 source 誘導的決策</strong></li><li>識別兩種診斷性失真模式：decontextualization（重點證據被保留但脫離解讀所需的 caveat/限定語境）與 model dependency（不同壓縮器產出不同詮釋）</li><li>提出 Agentic Context Compression：生成多個候選壓縮版本，對照原始 source 稽核彼此分歧</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>展示 LLM 壓縮可產出「可讀但改變決策」的金融摘要——壓縮評估應優先保留 decision-relevant context，而非只看效率與 factuality</li><li>具體量化數字：未取得（abstract 摘述未含）</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>領域限定於金融分析文本，其他決策場景泛化性未驗證</li><li>多候選壓縮 + 稽核帶來額外 inference 成本，abstract 未報成本開銷</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>直接對應 <code>.claude/skills/output-compress</code> 的<strong>機械失真閘</strong>設計動機：本文證明「壓縮後仍流暢可讀」≠「決策等價」，支持 whitelist 不變式（保重點白名單）優先於壓縮率。</li><li>decontextualization 模式正是 output-compress「安全紅線/不可逆確認語句不得壓縮」排除項的實證依據——caveat 脫落即決策失真。</li><li>Agentic Context Compression 的多候選+分歧稽核與 workspace 對抗互審（judge 偏誤控制）同構，可評估作為 fidelity gate 的升級選項。⚠️ 成本增量需 FinOps 評估。</li></ul>',16)])])}const p=a(r,[["render",s]]);export{m as __pageData,p as default};
